"use strict";(globalThis.webpackChunkdocumentation_web||=[]).push([[1622],{6150(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"documentationSidebar":[{"type":"link","href":"/PIPPA-documentation/ATACseq/easyIntro","label":"PIPPA overview","docId":"ATACseq/easyIntro","unlisted":false},{"type":"category","label":"Usage and explanation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/PIPPA-documentation/ATACseq/Usage/requisites","label":"Requisites","docId":"ATACseq/Usage/requisites","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/Usage/software","label":"Software","docId":"ATACseq/Usage/software","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/Usage/","label":"Configuration","docId":"ATACseq/Usage/usage","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/Usage/setUp","label":"0. Set up pipeline","docId":"ATACseq/Usage/setUp","unlisted":false}],"href":"/PIPPA-documentation/category/usage-and-explanation"},{"type":"category","label":"Stage 1 QC - sequencing quality","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 1/batchRunPreAnalysis","label":"1. Pre-analysis","docId":"ATACseq/QC Stage 1/batchRunPreAnalysis","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 1/batchCalcQCMetrics","label":"2. ATAC-seq QC metrics","docId":"ATACseq/QC Stage 1/batchCalcQCMetrics","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 1/samplePeaks","label":"3. Samples peak calling","docId":"ATACseq/QC Stage 1/samplePeaks","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 1/summaryS1","label":"4. Stage 1 summary","docId":"ATACseq/QC Stage 1/summaryS1","unlisted":false}],"href":"/PIPPA-documentation/category/stage-1-qc---sequencing-quality"},{"type":"category","label":"Stage 2 QC - confirmation of individual","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 2/sexChr","label":"5. Sex check","docId":"ATACseq/QC Stage 2/sexChr","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 2/genoCheck","label":"6. Genotype check","docId":"ATACseq/QC Stage 2/genoCheck","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 2/summaryS2","label":"7. Stage 2 summary","docId":"ATACseq/QC Stage 2/summaryS2","unlisted":false}],"href":"/PIPPA-documentation/category/stage-2-qc---confirmation-of-individual"},{"type":"category","label":"Stage 3 QC - cell type check","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/PIPPA-documentation/ATACseq/QC Stage 3/cellTypecheck","label":"8. Group peak calling","docId":"ATACseq/QC Stage 3/cellTypecheck","unlisted":false}],"href":"/PIPPA-documentation/category/stage-3-qc---cell-type-check"},{"type":"category","label":"Final - Peak set curation","collapsible":true,"collapsed":true,"items":[{"type":"link","href":"/PIPPA-documentation/ATACseq/Peak set curation/peakCur","label":"9. Peak set curation","docId":"ATACseq/Peak set curation/peakCur","unlisted":false},{"type":"link","href":"/PIPPA-documentation/ATACseq/Peak set curation/prepareDown","label":"10. Prepare for downstream analysis","docId":"ATACseq/Peak set curation/prepareDown","unlisted":false}],"href":"/PIPPA-documentation/category/final---peak-set-curation"},{"type":"link","href":"/PIPPA-documentation/ATACseq/slurmInfo","label":"SLURM information","docId":"ATACseq/slurmInfo","unlisted":false}]},"docs":{"ATACseq/easyIntro":{"id":"ATACseq/easyIntro","title":"PIPPA overview","description":"Pipeline for Integrative Peak calling in Population-scale ATAC-seq (PIPPA) provides end-to-end quality control and processing of ATAC-seq datasets and curated of reproducible peak sets. It is designed to run quality-control (QC) of samples in 3 stages, followed by a final stage of peak set curation.","sidebar":"documentationSidebar"},"ATACseq/Peak set curation/peakCur":{"id":"ATACseq/Peak set curation/peakCur","title":"9. Peak set curation","description":"This script performs the analysis and curation of peak sets using high-quality samples in order to produce a curated peak set that can be used for downstream analyses. Cell fractions to which samples belong to need to be specified in the config.txt file.","sidebar":"documentationSidebar"},"ATACseq/Peak set curation/prepareDown":{"id":"ATACseq/Peak set curation/prepareDown","title":"10. Prepare for downstream analysis","description":"This scripts prepares inputs for downstream analyses, especially counts in peaks matrices. Cell fractions to which samples belong to need to be specified in the config.txt file.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 1/batchCalcQCMetrics":{"id":"ATACseq/QC Stage 1/batchCalcQCMetrics","title":"2. ATAC-seq QC metrics","description":"Performs analysis of ATAC-seq-specific characteristics, including fragment size distribution and TSS enrichment scores.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 1/batchRunPreAnalysis":{"id":"ATACseq/QC Stage 1/batchRunPreAnalysis","title":"1. Pre-analysis","description":"Performs pre-analysis of ATAC-seq data, including pre-alignment quality control, alignment and post-alignment quality control of samples.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 1/samplePeaks":{"id":"ATACseq/QC Stage 1/samplePeaks","title":"3. Samples peak calling","description":"This script performs the core part of the ATACseq pipeline: calling peaks. In this stage, peak calling is performed at sample level using the paired-end mode of MACS3. After this, FRIP statistics are calculated and collated in a single csv file.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 1/summaryS1":{"id":"ATACseq/QC Stage 1/summaryS1","title":"4. Stage 1 summary","description":"This scripts collates results of Stage 1 of QC pipeline to confirm data quality. It uses MultiQC to collate the output of FastQC, Bowtie2 alignment, ATAC-seq QC metrics and sample peak calling results.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 2/genoCheck":{"id":"ATACseq/QC Stage 2/genoCheck","title":"6. Genotype check","description":"This script checks the genotype of the samples as part of their identity check by detecting possible DNA contamination in order to ensure high quality sequence reads. If any contamination is detected, possible swaps will be suggested.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 2/sexChr":{"id":"ATACseq/QC Stage 2/sexChr","title":"5. Sex check","description":"This script checks the sex of samples as part of their identity check by creating bam files for each sample containing only reads aligned to sex chromosomes and performing peak calling on these.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 2/summaryS2":{"id":"ATACseq/QC Stage 2/summaryS2","title":"7. Stage 2 summary","description":"This scripts collates results of Stage 2 of QC pipeline to confirm samples identity. Sex and genotype check results are collated.","sidebar":"documentationSidebar"},"ATACseq/QC Stage 3/cellTypecheck":{"id":"ATACseq/QC Stage 3/cellTypecheck","title":"8. Group peak calling","description":"This script performs stage 3 of QC to check cell type of samples by grouping samples per cell type, performing group level peak calling and gets read counts in peaks called. Samples used are those that have passed previous QC stages 1 and 2. Cell fractions to which samples belong to need to be specified in the config.txt file.","sidebar":"documentationSidebar"},"ATACseq/slurmInfo":{"id":"ATACseq/slurmInfo","title":"SLURM information","description":"PIPPA has been developed to be executed using SLURM workload manager,","sidebar":"documentationSidebar"},"ATACseq/Usage/requisites":{"id":"ATACseq/Usage/requisites","title":"Requisites","description":"To ensure PIPPA can run as expected, please check:","sidebar":"documentationSidebar"},"ATACseq/Usage/setUp":{"id":"ATACseq/Usage/setUp","title":"0. Set up pipeline","description":"This is an optional step of the pipeline. It will check that required files, packages or libraries that are as expected by the pipeline.","sidebar":"documentationSidebar"},"ATACseq/Usage/software":{"id":"ATACseq/Usage/software","title":"Software","description":"Several software are needed to run the pipeline. Some of these can be used from a conda. The set up script (0_setUpPipeline.sh) will create a conda environment where some of these packages will be installed by conda. As explained in Requisites, the condaEnv.yml file can be used to set up the conda environment. This can be done using either Anaconda or Miniconda, which local source directory needs to be specified in the config.txt file (CONDA). In order to download and install refer to: Anaconda or Miniconda","sidebar":"documentationSidebar"},"ATACseq/Usage/usage":{"id":"ATACseq/Usage/usage","title":"Configuration","description":"In order to use PIPPA, two main configuration files need to be set up. For examples of these config files, go to ATACSeq/config","sidebar":"documentationSidebar"},"extra-pages/about":{"id":"extra-pages/about","title":"About PIPPA","description":"Pipeline for Integrative Peak calling in Population-scale ATAC-seq (PIPPA) provides end-to-end quality control and processing of ATAC-seq datasets and curated of reproducible peak sets. The pipeline has been developed to work from raw FASTQ files all the way to curated peak sets that can be used for downstream analyses."},"extra-pages/help":{"id":"extra-pages/help","title":"Q&A about PIPPA","description":"Q. What sequencing data can I used?"},"intro":{"id":"intro","title":"Welcome to the documentation page for PIPPA","description":"Pipeline for Integrative Peak calling in Population-scale ATAC-seq (PIPPA) provides end-to-end quality control and processing of ATAC-seq datasets and curated of reproducible peak sets. The pipeline can be found at"},"QCpipeline":{"id":"QCpipeline","title":"QC pipeline overview","description":""},"tutorial-extras/manage-docs-versions":{"id":"tutorial-extras/manage-docs-versions","title":"Manage Docs Versions","description":"Docusaurus can manage multiple versions of your docs."},"tutorial-extras/translate-your-site":{"id":"tutorial-extras/translate-your-site","title":"Translate your site","description":"Let\'s translate docs/intro.md to French."}}}}')}}]);